/* Generated by Trae Work — 模块2(发布求助细化) & 模块3(求助详情+帮忙评论细化)
   策略：仅向既有容器内注入新增节点，不修改 app.js/app.css 的任何结构 */
(function(){
"use strict";
/* 注意：两个选择器都支持第二参数（作用域）。
   2026-10-19 修复：旧版 `$` 是单参数，导致 `$(".p-acts",card)` 静默变成全局查询，
   「查看完整求助」入口只被加到列表第一张卡片上（其它卡片永远没有入口）。 */
const $=(s,r)=>(r||document).querySelector(s), $$=(s,r)=>[...(r||document).querySelectorAll(s)];
const wait=ms=>new Promise(r=>setTimeout(r,ms));

/* ============ 状态 ============ */
const TAGS=["📚 学习辅导","💗 心理成长","💬 亲子沟通","🧳 亲子出行","🛡 健康安全","🎨 兴趣培养"];
const AGES=[["🍼","0-3岁"],["🧸","3-6岁"],["🎒","6-12岁"],["🎓","12-18岁"]];
const VIS=[["🌐","公开","所有人可见"],["🤝","仅好友","仅互相关注朋友"],["📍","同城","仅同城市家长"]];
const RP_REASONS=["垃圾营销信息","虚假/不实信息","不友善言论","违法违规内容","侵犯隐私泄露","未成年人不宜","其他"];
let tag=TAGS[0],age=2,urg=1,vis=0,recVid=null,recVoice=null,imgPicked=2,curDetail=null,recTimers=[];
/* mediaTouched：用户是否点选过「图片 / 微视频 / 语音」。
   拍照/相册、录制区只有在点选类型后才出现（打开面板时不预选任何类型） */
let mediaTouched=false;

/* ============ DOM 注入 ============ */
function injectAll(){
  /* —— 发布面板「瘦身」：只留 内容输入 + 语音转文字 + 媒体拍摄 + 公约
        问题分类 / 年龄段 / 紧急程度 / 位置 / 可见范围 全部挪到「发布确认页」，点发布时才弹，
        不选任何一项也能直接发布（由 AI 自动分类） —— */
  const pub=$("#publishSheet .sh-body");

  /* 拍摄/选择素材区：紧跟在「媒体类型」切换之后
     —— 只保留这一套真实录音/录像，去掉上方重复的示意预览区（#pubPrev 由 CSS 隐藏） */
  $("#pubTypes").insertAdjacentHTML("afterend",`<div id="r23Picker"></div>`);

  /* 协议勾选（与发布按钮同屏，属于发布前的同意项，不挪走） */
  pub.insertAdjacentHTML("beforeend",`
    <div class="r23-checks">
      <div class="r23-ck on" id="r23CkSafe"><span class="box"></span>遵守《未成年人保护公约》，不含隐私与定位原图</div>
      <div class="r23-ck on" id="r23CkReview"><span class="box"></span>发布前安全审核（推荐，约 2 秒）</div>
    </div>`);

  /* —— 发布确认页：点「发布求助」后弹出，AI 已自动分好类；不选任何一项也能发布 —— */
  $("#phone").insertAdjacentHTML("beforeend",`
    <div id="r23Confirm">
      <div class="r23Cf-head">
        <button class="r23Cf-back" id="r23CfClose" aria-label="返回">‹</button>
        <b>发布确认</b>
        <span class="r23Cf-tag">🤖 AI 自动分类</span>
      </div>
      <div class="r23Cf-body">
        <div class="r23Cf-ai">
          <div class="t">🤖 AI 已帮你分好类</div>
          <div class="r" id="r23CfAiRow">识别中…</div>
          <div class="s" id="r23CfAiTip">不满意可在下方点选修改；<b>不选任何一项也能直接发布</b>，后台 AI 会按内容自动归类。</div>
        </div>
        <div class="r23-label">标题 <span class="r23-hint">选填 · 留空就用 AI 拟的标题</span></div>
        <input id="r23Title" placeholder="一句话标题（可留空，例如：孩子不肯独自睡怎么办）">
        <div class="r23-label">问题分类 <span class="r23-hint">选填 · 已按内容预选</span></div>
        <div class="r23-tags" id="r23Tags">${TAGS.map((t,i)=>`<button class="r23-tag ${i===0?"on":""}" data-i="${i}">${t}</button>`).join("")}</div>
        <div class="r23-label">👶 孩子年龄段 <span class="r23-hint">按年龄给建议更科学</span></div>
        <div class="r23-vis" id="r23Age">${AGES.map(([ic,t],i)=>`<button class="${i===2?"on":""}" data-i="${i}"><b style="font-size:15px">${ic}</b>${t}</button>`).join("")}</div>
        <div class="r23-label">紧急程度 <span class="r23-hint">选填</span></div>
        <div class="r23-seg3" id="r23Urg">
          <button class="r23-urg on" data-u="1"><span class="ui">🌤</span>普通求助</button>
          <button class="r23-urg" data-u="2"><span class="ui">🔥</span>紧急求助</button>
          <button class="r23-urg" data-u="3"><span class="ui">🚨</span>十万火急</button>
        </div>
        <div id="r23Hotline">🛡️ <b>温馨提示</b>：如涉及孩子人身安全或心理危机，请立即拨打 <b>110</b>（报警）/ <b>120</b>（急救）；青少年服务热线 <b>12355</b>。社区互助不能代替专业救助。</div>
        <div class="r23-label">📍所在位置</div>
        <div class="r23-loc"><span class="li">📍</span><input id="r23Loc" value="${S.region.city}·${S.region.flag} 附近"><span class="reloc" id="r23Reloc">重新定位</span></div>
        <div class="r23-label">👁 可见范围</div>
        <div class="r23-vis" id="r23Vis">${VIS.map(([ic,t,d],i)=>`<button class="${i===0?"on":""}" data-i="${i}"><b style="font-size:16px">${ic}</b>${t}</button>`).join("")}</div>
        <div class="r23Cf-note">📣 发布后后台 AI 仍会复核一次分类：若与实际内容不符，会自动帮你调整到更合适的栏目。</div>
      </div>
      <div class="r23Cf-foot">
        <button class="btn-g" id="r23CfSkip">跳过，直接发布</button>
        <button class="btn-a" id="r23CfGo">确认发布</button>
      </div>
    </div>`);

  /* —— 详情页 / 大图查看 / 举报 / 审核流 —— */
  $("#phone").insertAdjacentHTML("beforeend",`
    <div id="r23Detail"></div>
    <div id="r23Viewer"><div class="big" id="r23Big"></div><button class="vx" id="r23Vx">✕</button></div>
    <div id="r23Report">
      <div class="sh-handle"></div>
      <div class="r23-rp-title">举报该求助 / 评论</div>
      <div class="r23-rp-grid" id="r23RpGrid">${RP_REASONS.map(r=>`<button data-r="${r}">${r}</button>`).join("")}</div>
      <button class="btn-a big" id="r23RpGo">提交举报</button>
    </div>
    <div id="r23Review">
      <div class="r23-ring"><i></i><span class="ic" id="r23RvIc">🛡️</span></div>
      <div class="r23-rv-title" id="r23RvT">正在提交求助…</div>
      <div class="r23-rv-steps" id="r23RvSteps"></div>
    </div>`);
  bindStatic();
  renderPicker();
}

/* ============ 素材选择器 ============ */
function pickerHTML(){
  const t=S.pubType;
  if(t==="img"){
    let cells="";
    for(let i=0;i<9;i++){
      if(i<imgPicked){cells+=`<div class="r23-pcell sel" data-i="${i}">${scene(i%2?"garden":"study")}<span class="ord">图${i+1}</span><span class="rm" data-rm="${i}">✕</span></div>`;}
      else cells+=`<div class="r23-pcell add" data-add="1"><span class="pl">＋</span><span class="ps">添加图片</span></div>`;
    }
    return `<div class="r23-pick9">${cells}</div>`;
  }
  if(t==="video"){
    if(!recVid){
      return `<div class="r23-rec idle" id="r23RecBox">
        <div class="rview">${scene("heart")}<div class="rph">点击下方按钮，现场拍摄 ≤30 秒微视频</div></div>
        <button class="r23-rbtn" id="r23RecBtn">🎥</button>
        <div class="r23-rline"><span>最长 <b>00:30</b></span><span>演示倒计时加速 10×</span></div></div>`;
    }
    if(recVid==="rec"){
      return `<div class="r23-rec recording" id="r23RecBox">
        <div class="rview">${scene("heart")}<span class="rrec"><span class="rdot"></span>REC</span><span class="r23-rcap" id="r23Cap">00:27</span></div>
        <div class="r23-rprog"><i id="r23Rprog"></i></div>
        <button class="r23-rbtn stop" id="r23StopBtn">■</button>
        <div class="r23-rline">已录制 <b id="r23RecT">00:27</b> / 00:30</div></div>`;
    }
    return `<div class="r23-rec" id="r23RecBox">
      <div class="rview">${scene("heart")}<div class="rrec">✅ 已完成</div><span class="r23-rcap">00:03</span></div>
      <div style="display:flex;gap:10px;justify-content:center;margin-top:12px">
        <button class="btn-g r23-retake" style="padding:10px 18px">重拍</button>
        <button class="btn-a" style="padding:10px 18px" id="r23UseVid">使用视频</button></div></div>`;
  }
  if(!recVoice){
    return `<div class="r23-voice">
      <button class="r23-vbtn" id="r23VBtn">🎤</button>
      <div class="r23-vwave" id="r23Vwave">${waveBars()}</div>
      <div style="font-size:12.5px;color:var(--muted)">点击录制语音求助 · 最长 60 秒</div></div>`;
  }
  if(recVoice==="rec"){
    return `<div class="r23-voice">
      <button class="r23-vbtn rec" id="r23VStop">■</button>
      <div class="r23-vwave live" id="r23Vwave">${waveBars()}</div>
      <div class="r23-vtime" id="r23Vtime">00:03</div>
      <div class="r23-vtip">录音中…再次点击结束</div></div>`;
  }
  return `<div class="r23-voice">
    <div style="display:flex;flex-direction:column;align-items:center;gap:10px">
      <button class="r23-vbtn" id="r23VPlay">▶</button>
      <div class="r23-vwave" id="r23Vwave">${waveBars()}</div>
      <div><span class="r23-vtime">语音 00:03</span>　<button class="btn-g r23-revoice" style="padding:6px 14px;font-size:12.5px">重录</button></div>
    </div></div>`;
}
function waveBars(){let s="";for(let i=0;i<34;i++)s+=`<i style="height:${14+Math.round(Math.abs(Math.sin(i*1.6))*80)}%;animation-delay:${(i%9)*0.07}s"></i>`;return s;}
const PICK_HINT=`<div class="r23-pick-hint">👆 点上方「图片 / 微视频 / 语音」<br>这里就会出现对应的拍照、录制按钮</div>`;
function renderPicker(){
  const host=$("#r23Picker");if(!host)return;
  /* 真实拍摄层（相机拍照/相册、真实录像、真实录音）；不可用时退回演示选择器 */
  if(window.YRB_CAPTURE){
    if(YRB_CAPTURE.unmount)YRB_CAPTURE.unmount();   /* 发布面板接管前，先解除帮忙面板的挂载 */
    if(YRB_CAPTURE.stopMedia)YRB_CAPTURE.stopMedia(host);  /* 重渲染前先停掉正在播放的视频/音频，避免浏览器小窗残留 */
    if(!mediaTouched){host.innerHTML=PICK_HINT;return;}
    host.innerHTML=YRB_CAPTURE.render(S.pubType);
    YRB_CAPTURE.bind(host);
    return;
  }
  if(!mediaTouched){host.innerHTML=PICK_HINT;return;}
  host.innerHTML=pickerHTML();bindPicker();
}

/* ============ 录制交互 ============ */
function bindPicker(){
  const add=$("[data-add]");if(add)add.onclick=()=>{
    if(imgPicked>=9){toast("最多上传 9 张图片");return;}
    imgPicked++;renderPicker();toast(`已选择图片 ${imgPicked} 张（演示）`);
  };
  $$("[data-rm]").forEach(b=>b.onclick=e=>{e.stopPropagation();/* 修复：删除任一已选图片=已选总数减1（旧逻辑 min(imgPicked,索引) 删除第1张会清空全部） */ if(imgPicked>0)imgPicked--;renderPicker();});
  const rb=$("#r23RecBtn");if(rb)rb.onclick=startVideoRec;
  const sb=$("#r23StopBtn");if(sb)sb.onclick=endVideoRec;
  const rt=$(".r23-retake");if(rt)rt.onclick=()=>{recVid=null;renderPicker();};
  const uv=$("#r23UseVid");if(uv)uv.onclick=()=>{recVid="done";renderPicker();toast("微视频已加入素材 🎬");};
  const vb=$("#r23VBtn");if(vb)vb.onclick=startVoiceRec;
  const vs=$("#r23VStop");if(vs)vs.onclick=endVoiceRec;
  const rv=$(".r23-revoice");if(rv)rv.onclick=()=>{recVoice=null;renderPicker();};
  const vp=$("#r23VPlay");if(vp)vp.onclick=toggleVoicePlay;
}
function clearTimers(){recTimers.forEach(clearInterval);recTimers=[];if(window.YRB_CAPTURE)YRB_CAPTURE.stopAll();}
function startVideoRec(){
  recVid="rec";renderPicker();
  let left=27;const cap=$("#r23Cap"),bar=$("#r23Rprog"),t=$("#r23RecT");
  bar.style.width="90%";
  const tm=setInterval(()=>{
    left++;cap.textContent="00:"+String(left).padStart(2,"0");t.textContent="00:"+String(left).padStart(2,"0");
    bar.style.width=(left/30*100)+"%";
    if(left>=30){clearInterval(tm);endVideoRec();}
  },1000);recTimers.push(tm);
  toast("正在拍摄…（演示 10× 加速）");
}
function endVideoRec(){clearTimers();recVid="done";renderPicker();toast("拍摄完成，预览后可重拍或使用");}
function startVoiceRec(){
  recVoice="rec";renderPicker();
  let n=0;const t=$("#r23Vtime");
  const tm=setInterval(()=>{n=Math.min(60,n+1);t.textContent="00:"+String(n).padStart(2,"0");if(n>=60)endVoiceRec();},1000);
  recTimers.push(tm);
}
function endVoiceRec(){clearTimers();recVoice="done";renderPicker();toast("语音录制完成，可试听或重录");}
function toggleVoicePlay(){
  const box=$("#r23VPlay").closest(".r23-voice"),wave=$("#r23Vwave");
  const playing=box.classList.toggle("playing");
  $("#r23VPlay").textContent=playing?"⏸":"▶";
}

/* ============ 拦截并增强发布 ============ */
function bindStatic(){
  $("#r23Tags").onclick=e=>{const b=e.target.closest(".r23-tag");if(!b)return;$$("#r23Tags .r23-tag").forEach(x=>x.classList.remove("on"));b.classList.add("on");tag=TAGS[+b.dataset.i];classManual=true;refreshAiCard();};
  $("#r23Age").onclick=e=>{const b=e.target.closest("#r23Age button");if(!b)return;$$("#r23Age button").forEach(x=>x.classList.remove("on"));b.classList.add("on");age=+b.dataset.i;classManual=true;refreshAiCard();};
  $("#r23Urg").onclick=e=>{const b=e.target.closest(".r23-urg");if(!b)return;$$("#r23Urg .r23-urg").forEach(x=>x.classList.remove("on"));b.classList.add("on");urg=+b.dataset.u;classManual=true;refreshAiCard();
    /* 科学性与未成年人保护：紧急求助时主动给出专业求助渠道 */
    $("#r23Hotline").classList.toggle("show",urg>=2);};
  $("#r23Vis").onclick=e=>{const b=e.target.closest("#r23Vis button");if(!b)return;$$("#r23Vis button").forEach(x=>x.classList.remove("on"));b.classList.add("on");vis=+b.dataset.i;};
  /* 发布确认页：返回 / 跳过（全按 AI 分类）/ 确认发布 */
  $("#r23CfClose").onclick=closePublishConfirm;
  $("#r23CfGo").onclick=()=>finishPublish(false);
  $("#r23CfSkip").onclick=()=>finishPublish(true);
  $("#r23Reloc").onclick=()=>toast("已重新定位："+S.region.city+" · 精度 50m（演示）");
  $("#r23CkSafe").onclick=()=>$("#r23CkSafe").classList.toggle("on");
  $("#r23CkReview").onclick=()=>$("#r23CkReview").classList.toggle("on");
  $("#r23Vx").onclick=()=>$("#r23Viewer").classList.remove("open");
  $("#r23Viewer").onclick=e=>{if(e.target.id==="r23Viewer")$("#r23Viewer").classList.remove("open");};
  $("#r23RpGrid").onclick=e=>{const b=e.target.closest("button");if(!b)return;$$("#r23RpGrid button").forEach(x=>x.classList.remove("on"));b.classList.add("on");};
  $("#r23RpGo").onclick=submitReport;

  /* 在 document 捕获阶段拦截发布（先于 #pubGo 上 app.js 的 bubble 监听器），改走增强流程 */
  document.addEventListener("click",function(ev){
    if(ev.target.closest("#pubGo")){ev.stopPropagation();ev.preventDefault();r23Publish();}
  },true);
  /* 未登录时点「🔒 登录后可查看」：直接弹出登录 */
  document.addEventListener("click",function(ev){
    if(ev.target.closest("[data-dlogin]")){
      ev.stopPropagation();ev.preventDefault();
      if(window.YRB_CLOUD&&YRB_CLOUD.openLogin)YRB_CLOUD.openLogin();
    }
  },true);
  /* 媒体类型切换后（app.js 在 bubble 阶段更新 S.pubType），重渲染素材选择器。
     拍照/相册、录制区只在用户点选类型后出现；切换时先停掉旧的视频/音频播放 */
  $("#pubTypes").addEventListener("click",e=>{
    if(e.target.closest(".seg-btn")){mediaTouched=true;setTimeout(()=>{clearTimers();recVid=null;recVoice=null;renderPicker();},0);}
  },true);
  /* 录制过程中从手柄关闭发布面板（✕ / 遮罩）：立即停止录制计时，避免 interval 泄漏空转
     —— 同时停掉面板里正在播放的视频/音频，浏览器的小窗播放器会立刻收起 */
  document.addEventListener("click",ev=>{
    if(ev.target.closest('[data-close="publishSheet"],#drMask')){
      closePublishConfirm();
      if(window.YRB_CAPTURE&&YRB_CAPTURE.stopMedia)YRB_CAPTURE.stopMedia($("#r23Picker"));
      if(recTimers.length){clearTimers();recVid=null;recVoice=null;setTimeout(renderPicker,0);}
    }
  },true);
  /* 打开发布面板时重置增强区（分类留给确认页，由 AI 现场识别）
     —— 媒体类型恢复"未选择"状态：拍照/相册、录制区要点选类型后才出现；
        同时先停掉上一次可能还在播放的视频/音频（浏览器小窗立即收起） */
  $("#fab").addEventListener("click",()=>{
    clearTimers();recVid=null;recVoice=null;imgPicked=2;
    mediaTouched=false;
    try{S.pubType="img";}catch(err){}
    $$("#pubTypes .seg-btn").forEach(x=>x.classList.remove("on"));
    if(window.YRB_CAPTURE)YRB_CAPTURE.reset(true);   /* true=先别画：下面统一 renderPicker 一次，避免双渲染闪烁 */
    classManual=false;aiGuess={tag:0,age:2,urg:1,title:"",confident:false};
    closePublishConfirm();
    $("#r23Title").value="";$("#r23Loc").value=S.region.city+"·"+S.region.flag+" 附近";
    $$("#r23Tags .r23-tag").forEach((x,i)=>x.classList.toggle("on",i===0));tag=TAGS[0];
    $$("#r23Age button").forEach((x,i)=>x.classList.toggle("on",i===2));age=2;
    $("#r23Hotline").classList.remove("show");
    $$("#r23Urg .r23-urg").forEach(x=>x.classList.toggle("on",+x.dataset.u===1));urg=1;
    $$("#r23Vis button").forEach((x,i)=>x.classList.toggle("on",i===0));vis=0;
    $("#r23CkSafe").classList.add("on");$("#r23CkReview").classList.add("on");
    setTimeout(renderPicker,0);
  },true);
  /* 卡片/评论面板：详情入口委托（捕获阶段，避开播放与帮忙逻辑） */
  document.addEventListener("click",e=>{
    const dl=e.target.closest("[data-r23detail]");if(dl){e.stopPropagation();openDetail(+dl.dataset.r23detail);}
  },true);
  /* 评论面板内交互委托 */
  document.addEventListener("click",e=>{
    const rb=e.target.closest("[data-rreply]");if(rb){e.stopPropagation();toggleReplyBox(+rb.dataset.rreply);return;}
    const rs=e.target.closest("[data-rsend]");if(rs){e.stopPropagation();sendReply(+rs.dataset.rsend);return;}
    const vb=e.target.closest("[data-rvplay]");if(vb){e.stopPropagation();playCommentMedia(vb);return;}
  },true);
  /* 帮忙条目 → 帮忙者名片（头像 / 昵称 / 内容都能点；按钮与播放器除外）
     —— 覆盖详情页 #r23CmList 与底部帮忙面板 #cmList 两处 */
  document.addEventListener("click",e=>{
    const item=e.target.closest(".cm-item");
    if(!item)return;
    if(e.target.closest("button,a,input,textarea,audio,video,.cm-media,.cm-voicebar,.cm-videobar,.r23-replybox,.r23-sub"))return;
    const list=e.target.closest("#r23CmList")||e.target.closest("#cmList");
    if(!list)return;
    const i=[...list.querySelectorAll(".cm-item")].indexOf(item);
    if(i<0)return;
    e.stopPropagation();
    openHelper(i,list.id==="r23CmList"?"detail":"sheet");
  },true);
  /* 详情页操作委托 */
  $("#r23Detail").addEventListener("click",e=>{
    if(e.target.closest("#r23DBack")){$("#r23Detail").classList.remove("open");return;}
    const b=e.target.closest("[data-db]");if(!b)return;
    const k=b.dataset.db;
    if(k==="solve")askSolve();
    else if(k==="report")openReport();
    else if(k==="like"||k==="fav"){b.classList.toggle("on");toast(b.classList.contains("on")?(k==="fav"?"已收藏 ⭐":"已点赞 ♥"):"已取消");}
    else if(k==="share"){try{window.YRB_CONSOLE&&YRB_CONSOLE.openShare?YRB_CONSOLE.openShare():toast("请复制浏览器地址栏的链接转发")}catch(err){toast("请复制浏览器地址栏的链接转发")}}
    else if(k==="help"){S.curPost=curDetail;renderComments();openSheet("commentSheet");}
    const v=e.target.closest(".r23-dvideo,.r23-dvoice");if(v)playDetailMedia(v);
    const di=e.target.closest(".di");if(di)openBigViewer(+di.dataset.i);
  });
  /* 评论面板重绘后注入媒体播放条 */
  new MutationObserver(()=>decorateCommentList()).observe($("#cmList"),{childList:true,subtree:true});
}

/* ============ 平台侧 AI 自动分类（本地轻量推断 + 后台 AI 复核） ============ */
const AI_TAG_KEYS=[
  [0,["作业","学习","成绩","考试","上课","数学","语文","英语","作文","背书","拖拉","专注","辅导","补习","写字","读书","课"]],
  [1,["情绪","哭","焦虑","紧张","害怕","恐惧","自卑","心理","脾气","生气","暴躁","抑郁","内向","胆小","委屈","崩溃"]],
  [2,["沟通","不听","顶嘴","叛逆","吵架","矛盾","不愿意","撒谎","说谎","不睡","分房","亲子","商量","拒绝","冷战"]],
  [3,["出行","旅游","周末","带娃去","攻略","景点","游乐园","自驾","高铁","飞机","露营","博物馆","科技馆"]],
  [4,["生病","发烧","咳嗽","过敏","医院","视力","近视","安全","校园","欺凌","打人","受伤","睡眠","饮食","挑食","身高","疫苗"]],
  [5,["兴趣","特长","绘本","阅读","钢琴","画画","运动","游泳","下棋","培养","习惯","足球","舞蹈","音乐","手工"]]
];
const AI_AGE_KEYS=[
  [0,["宝宝","婴儿","两岁","一岁","三岁","幼儿","托班","辅食","奶瓶"]],
  [1,["幼儿园","中班","大班","小班","学前","四岁","五岁","六岁"]],
  [2,["小学","三年级","四年级","五年级","作业","老师","七岁","八岁","九岁","十岁","少先"]],
  [3,["初中","高中","中学","青春期","中考","高考","十四","十五","十六","十七","住校","早恋"]]
];
const AI_URG_KEYS=[
  [3,["十万火急","走失","失踪","自残","自杀","离家出走","急救","马上要"]],
  [2,["急","在线等","紧急","受伤","发烧","今晚","明天一早","立刻"]]
];
let aiGuess={tag:0,age:2,urg:1,title:"",confident:false};
let classManual=false;      /* 用户是否手动点过分类（点过=尊重用户选择） */
let publishing=false;
const tagName=t=>String(t||"").replace(/^[^\s]+\s/,"");
function aiPick(text,keys,def){
  let best=def,hit=0;
  keys.forEach(([i,ws])=>{const n=ws.reduce((a,w)=>a+(text.includes(w)?1:0),0);if(n>hit){hit=n;best=i;}});
  return {i:best,hit};
}
function aiTitleOf(text){
  const first=String(text||"").replace(/\s+/g," ").split(/[。！？!?；;\n]/)[0].trim();
  return first.length>18?first.slice(0,18)+"…":first;
}
function aiClassify(text){
  const s=String(text||"");
  const tg=aiPick(s,AI_TAG_KEYS,0),ag=aiPick(s,AI_AGE_KEYS,2),ug=aiPick(s,AI_URG_KEYS,1);
  return {tag:tg.i,age:ag.i,urg:ug.i,title:aiTitleOf(s),confident:tg.hit>0};
}
function applyGuessToUI(){
  tag=TAGS[aiGuess.tag]||TAGS[0];
  $$("#r23Tags .r23-tag").forEach((x,i)=>x.classList.toggle("on",i===aiGuess.tag));
  age=aiGuess.age;
  $$("#r23Age button").forEach((x,i)=>x.classList.toggle("on",i===aiGuess.age));
  urg=aiGuess.urg;
  $$("#r23Urg .r23-urg").forEach(x=>x.classList.toggle("on",+x.dataset.u===aiGuess.urg));
  vis=0;$$("#r23Vis button").forEach((x,i)=>x.classList.toggle("on",i===0));
  $("#r23Hotline").classList.toggle("show",aiGuess.urg>=2);
}
function refreshAiCard(){
  const row=$("#r23CfAiRow");if(!row)return;
  const URG_T=["","🌤 普通求助","🔥 紧急求助","🚨 十万火急"];
  const curTag=tag||TAGS[aiGuess.tag],curAge=(AGES[age]||AGES[aiGuess.age])[1],curUrg=URG_T[urg]||URG_T[aiGuess.urg];
  row.innerHTML=`<span class="c on">${curTag}</span><span class="c on">${(AGES[age]||AGES[aiGuess.age])[0]} ${curAge}</span><span class="c on">${curUrg}</span>`;
  const tip=$("#r23CfAiTip");
  if(tip)tip.innerHTML=classManual
    ? `已按你选的分类发布（AI 原判：${TAGS[aiGuess.tag]} · ${AGES[aiGuess.age][1]}）。<b>不选也没关系</b>，后台 AI 会按内容自动归类。`
    : (aiGuess.confident
        ? "按内容自动识别，<b>现在就能直接发布</b>；也可以点选修改。"
        : "内容里没有明显的分类特征，<b>直接发布会由后台 AI 归类</b>；也可以点选修改。");
}

/* ============ 增强发布主流程（分两步：内容 → 确认页分类 → 发布） ============ */
function openPublishConfirm(body){
  aiGuess=aiClassify(body);
  classManual=false;
  applyGuessToUI();
  const qt=window.__yrbQuickTitle||"";window.__yrbQuickTitle="";
  const t=$("#r23Title");
  t.value=qt||aiGuess.title||"";
  t.placeholder=aiGuess.title?`建议标题：${aiGuess.title}`:"一句话标题（可留空）";
  refreshAiCard();
  $("#r23Confirm").classList.add("open");
}
function closePublishConfirm(){$("#r23Confirm").classList.remove("open");}

/* 第一步：内容与素材校验 —— 只校验「内容 / 素材 / 公约」，不再卡标题和分类 */
async function r23Publish(){
  const body=$("#pubText").value.trim();
  if(!body){toast("用「语音转文字」说一句，或写一点描述吧～");$("#pubText").focus();return;}
  const doReview=$("#r23CkReview").classList.contains("on");
  if(!$("#r23CkSafe").classList.contains("on")){toast("需先同意《未成年人保护公约》");return;}
  /* 校验素材：优先走真实拍摄层（照片/视频/语音），未加载时退回演示校验 */
  if(window.YRB_CAPTURE){
    const err=YRB_CAPTURE.validate(S.pubType);
    if(err){toast(mediaTouched?err:"请先点上方选择「图片 / 微视频 / 语音」并添加素材");return;}
  }else{
    if(S.pubType==="img"&&imgPicked===0){toast("请至少添加 1 张图片，或切换媒体类型");return;}
    if(S.pubType==="video"&&recVid!=="done"){toast("请先完成微视频拍摄");return;}
    if(S.pubType==="voice"&&recVoice!=="done"){toast("请先完成语音录制");return;}
  }
  openPublishConfirm(body);
}

/* 第二步：确认页 → 真正发布（skipAi=true 表示完全按 AI 分类，用户没做选择） */
async function finishPublish(skipAi){
  if(publishing)return;
  const body=$("#pubText").value.trim();
  if(!body){closePublishConfirm();toast("求助内容为空，请补充一句描述");return;}
  if(skipAi){classManual=false;applyGuessToUI();}
  const title=($("#r23Title").value.trim())||aiGuess.title||aiTitleOf(body);
  const loc=$("#r23Loc").value.trim()||(S.region.city+" 附近");
  const doReview=$("#r23CkReview").classList.contains("on");
  publishing=true;
  closePublishConfirm();
  closeSheet("publishSheet");
  try{
    if(doReview)await runReviewFlow();
    const t=S.pubType;
    const items=window.YRB_CAPTURE?YRB_CAPTURE.collect(t):[];
    const capDur=window.YRB_CAPTURE?YRB_CAPTURE.duration(t):"";
    const payload={type:t,title,text:body,tag:tagName(tag),tagFull:tag,
      age:AGES[age]?AGES[age][1]:"",urg,vis,loc};

  /* 真实上传 + 入库（未配置/未登录/失败都退化为本机保存，绝不丢用户素材） */
  let media=[],cloudId=null,cloudOk=false;
  if(window.YRB_CLOUD&&YRB_CLOUD.enabled()){
    const res=await YRB_CLOUD.publishPost(payload,items);
    if(res.ok){
      media=res.media||[];cloudId=res.cloudId;cloudOk=true;
    }else if(res.reason==="cancel"){
      toast("已取消发布：登录后才能把求助和素材上传到云端");
      return;
    }else if(res.reason==="auth"){
      /* 登录过期（2026-10-25）：素材先保本机，同时直接弹出重新登录，不让用户猜 */
      toast((res.message||"登录已过期，请重新登录后再发布")+"；内容已先保留在本机");
      media=(items||[]).map(it=>({kind:it.kind,path:"",url:URL.createObjectURL(it.blob),dur:it.dur||""}));
      if(window.YRB_CLOUD&&YRB_CLOUD.openLogin)setTimeout(()=>{try{YRB_CLOUD.openLogin();}catch(e){}},800);
    }else{
      toast("云端上传失败："+(res.message||"网络异常")+"，已先保存到本机");
      media=(items||[]).map(it=>({kind:it.kind,path:"",url:URL.createObjectURL(it.blob),dur:it.dur||""}));
    }
  }else{
    media=(items||[]).map(it=>({kind:it.kind,path:"",url:URL.createObjectURL(it.blob),dur:it.dur||""}));
    if(items&&items.length)toast("云服务未连接，素材已先保存在本机（离线演示）");
  }

  const p={id:uid(),mine:true,user:(window.YRB_CLOUD&&YRB_CLOUD.signedIn())?YRB_CLOUD.name():"阳阳爸爸",flag:S.region.flag,type:t,
    title,tag:tagName(tag),tagFull:tag,age:AGES[age]?AGES[age][1]:"",urg,vis,loc,
    text:body,status:"open",r23Status:doReview?"reviewing":"open",aiClassified:!classManual,
    time:"刚刚",likes:0,liked:false,favs:0,faved:false,helps:0,comments:[],roses:[],
    media,cloudId,__cloud:cloudOk};
  if(t==="img"){p.kinds=["study","garden","heart"].slice(0,Math.max(1,Math.min(3,media.length)));}
  if(t==="video"){p.kind="heart";p.dur=capDur||"00:03";}
  if(t==="voice"){p.dur=capDur||"00:03";}
  S.posts.unshift(p);S.published++;
  $("#pubText").value="";
  if(window.YRB_CAPTURE)YRB_CAPTURE.reset();
  switchTab("home");S.hotMode=false;renderFuncRow();renderFeed();
  enhanceCard(p.id,p.r23Status);
  toast(cloudOk?"求助已发布到云端，等待温柔的帮忙 🌸":"求助已提交，等待温柔的帮忙 🌸");
  if(!classManual)wait(1600).then(()=>toast("🤖 后台 AI 已完成分类："+tagName(tag)+" · "+(AGES[age]?AGES[age][1]:"")));
  if(doReview){
    wait(2400).then(()=>{p.r23Status="open";enhanceCard(p.id,"open");toast("审核通过，求助已公开发布 ✅");});
  }
  /* autoHelp 模拟帮忙已下线（2026-10-25）：真实帮忙来自云端 yb_comments */
  }finally{
    publishing=false;
  }
}
function runReviewFlow(){
  return new Promise(res=>{
    const steps=[["提交求助内容","加密上传中"],["AI + 人工安全审核","未成年人保护 · 隐私打码校验"],["发布成功","进入帮忙匹配"]];
    $("#r23RvSteps").innerHTML=steps.map((s,i)=>`<div class="st" data-i="${i}"><span class="n">${i+1}</span>${s[0]}<span style="margin-left:auto;font-size:11px">${s[1]}</span></div>`).join("");
    $("#r23Review").classList.add("open");
    [0,1,2].forEach(i=>setTimeout(()=>{
      const el=$(`#r23RvSteps .st[data-i="${i}"]`);el.classList.add("done");
      if(i<2)$(`#r23RvSteps .st[data-i="${i+1}"]`).classList.add("cur");
      if(i===0)$("#r23RvIc").textContent="🔍";
      if(i===1)$("#r23RvIc").textContent="🛡️";
    },i*750+120));
    setTimeout(()=>{$("#r23RvIc").textContent="🎉";$("#r23RvT").textContent="发布成功";
      setTimeout(()=>{$("#r23Review").classList.remove("open");res();},650);},2350);
  });
}

/* 给 feed 中的卡片注入「查看完整求助」入口与状态角标 */
function enhanceCard(id,status){
  const card=$(`.card[data-id="${id}"]`);if(!card)return;
  if(!$(".r23-detail-link",card)){
    const acts=$(".p-acts",card);
    if(acts)acts.insertAdjacentHTML("beforeend",`<button class="r23-detail-link" data-r23detail="${id}">📄 查看完整求助<span class="ar">›</span></button>`);
  }
  /* 没有状态就不需要角标占位（否则每张卡片都多一个空 div） */
  if(!status){
    const old=$(".r23-card-status",card);
    if(old)old.remove();
    return;
  }
  let badge=$(".r23-card-status",card);
  if(!badge){
    const txt=card.querySelector(".p-text");
    if(!txt)return;
    badge=document.createElement("div");badge.className="r23-card-status";txt.before(badge);
  }
  /* 关键守卫：状态未变化时绝不重写 innerHTML。否则 body 上的 MutationObserver(childList+subtree)
     会因 innerHTML 反复销毁/重建子节点而被无限微任务触发，导致发布后主线程假死 */
  if(badge.dataset.st!==status){
    badge.dataset.st=status;
    if(status==="reviewing"){badge.innerHTML=`<span class="hot-badge" style="background:linear-gradient(135deg,#8B7BE0,#6E56C7);box-shadow:none">🛡 审核中</span>`;}
    else if(status==="solved"){badge.innerHTML=`<span class="hot-badge" style="background:var(--gradT);box-shadow:none">✅ 已解决</span>`;}
    else badge.innerHTML="";
  }
}
/* 状态角标补扫：body 上的 DOM 变动极其频繁（打开面板、插入缩略图、toast…），
   旧实现每个 mutation 回调都同步遍历全部帖子并做全局选择器查询，
   手机上一次选图能触发上百次查询 —— 这也是「点 + 上传卡」的一部分。
   改为：16ms 内多次变动只跑一次，且只遍历「当前真正在列表里的卡片」。
   顺带修掉本地种子帖没有「查看完整求助」入口的问题（只要卡片上缺入口就补一次）。 */
let enhScheduled=false;
function enhanceAllCards(){
  enhScheduled=false;
  if(!S||!S.posts)return;
  const cards=document.querySelectorAll("#feed .card[data-id]");
  for(const card of cards){
    const id=+card.dataset.id;
    const p=S.posts.find(x=>x.id===id);
    if(!p)continue;
    const needLink=!card.querySelector(".r23-detail-link");
    const needBadge=!!p.r23Status&&!card.querySelector(".r23-card-status");
    if(needLink||needBadge)enhanceCard(id,p.r23Status||"");
  }
}
new MutationObserver(()=>{
  if(enhScheduled)return;
  enhScheduled=true;
  setTimeout(enhanceAllCards,16);
}).observe(document.body,{childList:true,subtree:true});

/* ============ 评论媒体播放条注入 ============ */
function decorateCommentList(){
  $$("#cmList .cm-item").forEach(it=>{
    if(it.dataset.decorated)return;
    const media=$(".cm-media",it);if(!media){return;}
    /* 真实录制/云端同步的语音与视频：保留真实播放器，不能替换成演示条（否则点了不出声） */
    if(media.classList.contains("cm-real")){it.dataset.decorated="1";return;}
    const idx=[...$$("#cmList .cm-item")].indexOf(it);
    it.dataset.decorated="1";
    const p=S.posts.find(x=>x.id===S.curPost);if(!p)return;
    const c=p.comments[idx];if(!c)return;
    if(c.kind==="voice"){
      media.outerHTML=`<div class="cm-voicebar" data-rvplay="1"><span class="vb-ic">▶</span><span class="vb-wave">${Array.from({length:16},(_,i)=>`<i style="height:${20+Math.round(Math.abs(Math.sin(i*1.8))*70)}%"></i>`).join("")}</span><span class="vb-d">${c.dur}</span></div>`;
    }else if(c.kind==="video"){
      media.outerHTML=`<div class="cm-videobar" data-rvplay="1"><span class="vt-ic">🎬</span><span class="vt-t">微视频帮忙</span><span class="vt-d">${c.dur} · ≤20s</span></div>`;
    }
  });
}
function playCommentMedia(el){
  const playing=el.classList.toggle("playing");
  if(el.classList.contains("cm-voicebar"))$(".vb-ic",el).textContent=playing?"⏸":"▶";
  else $(".vt-t",el).textContent=playing?"播放中…":"▶ 播放微视频";
}

/* ============ 楼中楼回复 ============ */
function toggleReplyBox(i){
  let box=$(`.r23-replybox[data-i="${i}"]`);
  if(!box){
    const item=$$("#cmList .cm-item")[i]||$$("#r23Detail .cm-item")[i];
    if(!item)return;
    item.insertAdjacentHTML("afterend",`
      <div class="r23-sub" data-sub="${i}"></div>
      <div class="r23-replybox" data-i="${i}"><input placeholder="温柔回复…"><button class="rbtn" data-rsend="${i}">回复</button></div>`);
    box=$(`.r23-replybox[data-i="${i}"]`);
    renderReplies(i);
  }
  box.classList.toggle("open");
}
function renderReplies(i){
  const p=S.posts.find(x=>x.id===S.curPost)||S.posts.find(x=>x.id===curDetail);if(!p)return;
  const c=p.comments[i];if(!c)return;c.replies=c.replies||[];
  const host=$(`.r23-sub[data-sub="${i}"]`);if(!host)return;
  host.innerHTML=c.replies.length?c.replies.map(r=>`<div class="r23-sub-it"><span class="sn">${esc(r.user)}：</span><span class="st">${esc(r.text)}</span></div>`).join(""):`<div style="font-size:11.5px;color:var(--muted);padding:2px 2px 4px">还没有回复，来说第一句吧</div>`;
}
function sendReply(i){
  const inp=$(`.r23-replybox[data-i="${i}"] input`);if(!inp)return;
  const v=inp.value.trim();
  if(!v){toast("写点回复再发送吧～");return;}
  inp.value="";
  const p=S.posts.find(x=>x.id===S.curPost)||S.posts.find(x=>x.id===curDetail);
  if(!p||!p.comments[i])return;
  p.comments[i].replies=p.comments[i].replies||[];
  p.comments[i].replies.push({user:"阳阳爸爸",text:v});
  renderReplies(i);
  if($("#r23Detail").classList.contains("open"))renderDetail();
  toast("回复已送达 💬");
}

/* ============ 求助详情页 ============ */
function mediaList(p){
  /* 真实媒体优先：云端上传的图片/视频/语音按真实元素渲染 */
  const rm=(p.media||[]).filter(m=>m&&m.url);
  if(rm.length){
    if(p.type==="img"){
      return `<div class="r23-dimgs ${rm.length===1?"one":""}">${rm.map((m,i)=>`<div class="di" data-i="${i}"><img class="real-img" src="${esc(m.thumbUrl||m.url)}" data-full="${esc(m.url)}" alt="图片${i+1}" loading="lazy"><span class="zi">图 ${i+1}/${rm.length}</span></div>`).join("")}</div>`;
    }
    if(p.type==="video"){
      return `<div class="r23-dvideo real"><video src="${esc(rm[0].url)}" controls playsinline preload="metadata"></video><span class="vdur">▶ ${esc(p.dur||"")}</span></div>`;
    }
    return `<div class="r23-dvoice real"><audio src="${esc(rm[0].url)}" controls preload="metadata"></audio><span class="vd">语音 ${esc(p.dur||"")}</span></div>`;
  }
  /* 云端帖带素材但未登录：明确提示，避免用示意图造成误会 */
  const hasMedia=(p.media||[]).filter(m=>m&&(m.path||m.url)).length;
  if(hasMedia&&p.__cloud){
    const w=(p.media[0]&&p.media[0].kind)==="video"?"视频":(p.media[0]&&p.media[0].kind)==="voice"?"语音":"照片";
    return `<div class="r23-dlocked" data-dlogin="1">🔒 这条求助有 ${hasMedia} 个${w}，登录后可查看</div>`;
  }
  if(p.type==="img"){
    const ks=p.kinds||["study"];
    return `<div class="r23-dimgs ${ks.length===1?"one":""}">${ks.map((k,i)=>`<div class="di" data-i="${i}">${scene(k)}<span class="zi">图 ${i+1}/${ks.length}</span></div>`).join("")}</div>`;
  }
  if(p.type==="video"){
    return `<div class="r23-dvideo" id="r23DVideo">${scene(p.kind||"heart")}<span class="vply"><b><svg viewBox="0 0 24 24"><path d="M7 4 L20 12 L7 20 Z"/></svg></b></span><span class="vdur">▶ ${p.dur||"0:28"} · ≤30s</span><span class="vprog"></span></div>`;
  }
  return `<div class="r23-dvoice" id="r23DVoice"><span class="vic"><svg viewBox="0 0 24 24" fill="#fff"><path d="M7 4 L20 12 L7 20 Z"/></svg></span><span class="vwave">${Array.from({length:28},(_,i)=>`<i style="height:${16+Math.round(Math.abs(Math.sin(i*1.5))*76)}%;animation-delay:${(i%10)*0.06}s"></i>`).join("")}</span><span class="vd">语音 ${p.dur||"0:15"} · 点击播放</span></div>`;
}
function detailCommentHTML(c,i){
  let body;
  if(c.kind==="voice")body=`<div class="cm-voicebar" data-rvplay="1"><span class="vb-ic">▶</span><span class="vb-wave">${Array.from({length:16},(_,k)=>`<i style="height:${20+Math.round(Math.abs(Math.sin(k*1.8))*70)}%"></i>`).join("")}</span><span class="vb-d">${c.dur}</span></div>`;
  else if(c.kind==="video")body=`<div class="cm-videobar" data-rvplay="1"><span class="vt-ic">🎬</span><span class="vt-t">微视频帮忙</span><span class="vt-d">${c.dur} · ≤20s</span></div>`;
  else body=`<div class="cm-content" style="margin:2px 0">${esc(c.text)}</div>`;
  return `<div class="cm-item">
    <div class="cm-ava">${c.user==="阳阳爸爸"?myAvaSVG():avatarSVG(c.ava)}</div>
    <div class="cm-main"><div class="cm-name">${esc(c.user)} ${esc(c.flag||"")} <span class="cm-kind">帮忙</span></div>${body}
    <div class="cm-acts"><button class="clike ${c.liked?"on":""}" data-dclike="${i}">♥ <span>${c.likes+(c.liked?1:0)}</span></button>
      <button class="gift" data-dcgift="${i}">🍽️ 送美食</button>
      <button data-rreply="${i}">💬 回复 ${(c.replies&&c.replies.length)||""}</button></div>
    <div class="r23-sub" data-dsub="${i}"></div></div>
  </div>`;
}
let __odAt=0,__odId=null;
/* 标题是否与正文重复：没填标题时系统会用正文首句截断当标题（aiTitleOf），
   详情页正文已完整展示，重复标题既占地方又会让朗读读两遍（2026-10-25 用户反馈）。
   返回 true = 详情里不显示标题行 */
function titleRedundant(p){
  const t=String((p&&p.title)||"").trim(),x=String((p&&p.text)||"").trim();
  if(!t)return true;
  if(!x||t===x)return !x||t===x;
  const b=t.replace(/[…]+$/,"").replace(/\.{3}$/,"").trim();
  return !!b&&x.replace(/\s+/g," ").indexOf(b.replace(/\s+/g," "))===0;
}
function openDetail(id){
  /* 同一条求助 80ms 内重复打开直接忽略：防止「自动重开详情」与 DOM 观察者互相触发形成点击风暴 */
  const now=Date.now();
  if(__odId===id&&now-__odAt<80)return;
  __odAt=now;__odId=id;
  const p=S.posts.find(x=>x.id===id);if(!p)return;
  curDetail=id;S.curPost=id;
  const solved=p.r23Status==="solved";
  $("#r23Detail").innerHTML=`
    <div class="r23-dhead"><button class="r23-dback" id="r23DBack">‹</button><b class="sp-title">求助详情</b><span style="margin-left:auto;font-size:11.5px;color:var(--muted)">${p.time}</span></div>
    <div class="r23-dbody">
      <div class="r23-dcard">
        <div class="p-head">
          <div class="p-ava">${p.mine?myAvaSVG():avatarSVG(p.ava)}</div>
          <div><div class="p-name">${esc(p.user)} ${esc(p.flag||"")}</div></div>
          <span class="p-tag">${esc(p.tagFull||p.tag||"求助")}</span>${p.age?`<span class="age-chip">👶 ${esc(p.age)}</span>`:""}
        </div>
        ${p.urg>=2?`<div style="margin:10px 0 0"><span class="hot-badge" style="background:linear-gradient(135deg,#FF7A6B,#E8443A)">${p.urg===3?"🚅 十万火急":"🔥 紧急求助"}</span></div>`:""}
        ${titleRedundant(p)?"":`<div class="p-text" style="font-size:16px;font-weight:800;margin:12px 2px 4px">${esc(p.title||"")}</div>`}
        <div class="p-text">${esc(p.text)}</div>
        ${mediaList(p)}
        <div class="r23-status ${solved?"s2":"s1"}"><span class="si">${solved?"✅":"🤝"}</span>${solved?"这个求助已解决，感谢大家的帮忙":`已有 <b>${p.helps}</b> 位家长伸出援手`}${p.mine?`<button class="r23-solve ${solved?"done":""}" data-db="solve">${solved?"已解决":"标记已解决"}</button>`:""}</div>
        <div style="font-size:11.5px;color:var(--muted);display:flex;gap:14px">可见范围：${(VIS[p.vis||0]||VIS[0])[1]}　·　评论需文明友善</div>
      </div>
      <div class="r23-dcard r23-rosecard"><h4>🌹 收到的感谢玫瑰（${(p.roses||[]).length}）</h4>
        <div class="r23-rosewall">${(p.roses||[]).length?p.roses.map(r=>`<span class="r"><span class="ri">🌹</span>${r}</span>`).join(""):'<span style="font-size:12.5px;color:var(--muted)">还没有玫瑰——为有帮助的「帮忙」点赞，玫瑰就会送达</span>'}</div>
      </div>
      <div class="r23-dcard"><div class="r23-cmhead">🤝 帮忙评论 <span class="n">${p.comments.length}</span></div><div id="r23CmList">${p.comments.map(detailCommentHTML).join("")}</div></div>
    </div>
    <div class="r23-dbottom">
      <button class="r23-db-btn ${p.liked?"on":""}" data-db="like"><svg viewBox="0 0 24 24"><path d="M12 20s-7-4.6-9.2-9C1.2 8 3 4.5 6.2 4.5c2 0 3.3 1.1 5.8 3.2 2.5-2.1 3.8-3.2 5.8-3.2 3.2 0 5 3.5 3.4 6.5C19 15.4 12 20 12 20z"/></svg>${p.likes+(p.liked?1:0)}</button>
      <button class="r23-db-btn fav ${p.faved?"on":""}" data-db="fav"><svg viewBox="0 0 24 24"><path d="M12 3.5l2.6 5.4 5.9.8-4.3 4.1 1.1 5.8L12 16.8l-5.3 2.8 1.1-5.8L3.5 9.7l5.9-.8z"/></svg>${p.favs+(p.faved?1:0)}</button>
      <button class="r23-db-btn" data-db="share"><svg viewBox="0 0 24 24"><circle cx="6" cy="12" r="2.6"/><circle cx="17.5" cy="6" r="2.6"/><circle cx="17.5" cy="18" r="2.6"/><path d="M8.3 10.8l6.9-3.6M8.3 13.2l6.9 3.6"/></svg>分享</button>
      <button class="r23-db-btn" data-db="report"><svg viewBox="0 0 24 24"><path d="M12 3l8 3v6c0 5-3.4 8-8 9-4.6-1-8-4-8-9V6z"/><line x1="9" y1="10" x2="15" y2="16"/><line x1="15" y1="10" x2="9" y2="16"/></svg>举报</button>
      <button class="r23-db-btn help" data-db="help">🤝 我也来帮忙</button>
    </div>`;
  $$("#r23CmList .cm-item").forEach((it,i)=>{
    const c=p.comments[i];
    if(c.replies&&c.replies.length){
      const host=$(`[data-dsub="${i}"]`,it);
      host.innerHTML=c.replies.map(r=>`<div class="r23-sub-it"><span class="sn">${esc(r.user)}：</span><span class="st">${esc(r.text)}</span></div>`).join("");
      const btn=$(`[data-rreply="${i}"]`,it);btn.append(document.createTextNode(" "+c.replies.length));
    }
    const lk=$(`[data-dclike="${i}"]`,it);if(lk)lk.onclick=()=>{c.liked=!c.liked;lk.classList.toggle("on");$("span",lk).textContent=c.likes+(c.liked?1:0);if(c.liked)setTimeout(()=>sendRose(p,i),500);};
    const gt=$(`[data-dcgift="${i}"]`,it);if(gt)gt.onclick=()=>sendRose(p,i);
  });
  $("#r23Detail").classList.add("open");
}
function playDetailMedia(v){
  const playing=v.classList.toggle("playing");
  if(v.classList.contains("r23-dvideo")){
    $(".vply b",v).style.opacity=playing?"0":"";
    $(".sc",v)&&$(".sc",v).remove();
  }else{
    $(".vic",v).innerHTML=playing?`<svg viewBox="0 0 24 24" fill="#fff"><rect x="6" y="5" width="4" height="14" rx="1"/><rect x="14" y="5" width="4" height="14" rx="1"/></svg>`:`<svg viewBox="0 0 24 24" fill="#fff"><path d="M7 4 L20 12 L7 20 Z"/></svg>`;
  }
}
function openBigViewer(i){
  const p=S.posts.find(x=>x.id===curDetail);if(!p||p.type!=="img")return;
  const rm=(p.media||[]).filter(m=>m&&m.url);
  if(rm.length){
    const u=(rm[i]||rm[0]).url;
    $("#r23Big").innerHTML=`<img src="${esc(u)}" alt="查看大图" style="width:100%;display:block">`;
    $("#r23Viewer").classList.add("open");
    return;
  }
  const k=(p.kinds||["study"])[i]||"study";
  $("#r23Big").innerHTML=scene(k);
  $("#r23Viewer").classList.add("open");
}
function askSolve(){
  const p0=(S&&S.posts||[]).find(x=>x.id===curDetail);
  if(!p0){toast("没找到这条求助，请返回列表再试一次");return;}
  /* 2026-10-25 收权：只有求助发布者本人能标记已解决（按钮已不渲染，此处兜底防旧 DOM/调试台触发） */
  if(!p0.mine){toast("只有求助的发布者可以标记已解决");return;}
  if(p0.r23Status==="solved"){toast("这条求助已经标记为「已解决」啦 ✅");return;}
  modal(`<div class="md-title">标记求助已解决？</div>
    <p style="font-size:13px;color:var(--muted);text-align:center;line-height:1.7">标记后，其他家长将看到「✅ 已解决」<br>记得给真正帮到你的「帮忙」点赞送玫瑰 🌹</p>
    <div class="md-acts"><button class="btn-g" data-x="close">再想想</button><button class="btn-a" id="r23SolveOk">确认已解决</button></div>`);
  const ok=$("#r23SolveOk");
  if(ok)ok.onclick=()=>{
    /* 防连点：真机上一次误触两次会把详情页重绘两遍，老人容易以为卡死 */
    if(ok.dataset.busy)return;
    ok.dataset.busy="1";
    try{
      const p=S.posts.find(x=>x.id===curDetail);
      if(!p){closeModal();toast("没找到这条求助，请返回列表再试一次");return;}
      p.r23Status="solved";closeModal();
      renderDetail();enhanceCard(p.id,"solved");renderMe&&renderMe();
      toast("已标记解决，感谢温暖的大家 🌹");
      /* 云端帖：状态落库（库端校验只有发布者能标记），失败不打断本地状态 */
      if(p.__cloud&&p.cloudId&&window.YRB_CLOUD&&YRB_CLOUD.solvePost){
        YRB_CLOUD.solvePost(p.cloudId).then(r=>{
          if(r&&r.ok)return;
          if(r&&r.reason==="auth"){toast(r.message||"登录已过期，请重新登录");return;}
          /* 库端拒绝（非发布者）时回滚本地状态，保持两端一致 */
          p.r23Status="open";
          __odAt=0;renderDetail();enhanceCard(p.id,"open");   /* 清防重入时间戳，否则 80ms 守卫会吞掉这次重绘 */
          toast((r&&r.message)||"标记未能保存，请稍后再试");
        });
      }
    }catch(err){
      console.warn("[标记已解决]",err);
      closeModal();toast("标记出了点小问题，请再试一次");
    }finally{
      setTimeout(()=>{try{delete ok.dataset.busy;}catch(e){}},600);
    }
  };
}
/* ============ 帮忙者名片：知道是谁帮的，并当场送美食 / 送玫瑰 ============ */
/* 2026-10-19 用户需求：「自己发布的求助发布后，下面的几个帮助应该能点开查看谁发的，
   同时可以给他送美食系列和玫瑰花」→ 点帮忙条目任意非按钮区域弹出名片。 */
function helperQuote(c){
  if(!c)return "";
  if(c.kind==="voice")return `🎙️ 一段 ${esc(c.dur||"")} 的语音帮忙`;
  if(c.kind==="video")return `📹 一段 ${esc(c.dur||"")} 的微视频帮忙`;
  const t=String(c.text||"").trim();
  if(!t)return "（这条帮忙没有附文字，点「回复」可以问问 TA）";
  return esc(t.length>72?t.slice(0,72)+"…":t);
}
/* 玫瑰写入云端：让对方在「我的 → 钱包 / 收到的答谢」里真的能收到。
   没有对方 uid（本机演示帮忙）时只播动画，不写库。 */
function sendRoseToCloud(p,c){
  try{
    const C=window.YRB_CLOUD;
    if(!C||typeof C.enabled!=="function"||!C.enabled())return;
    if(typeof C.signedIn!=="function"||!C.signedIn())return;
    if(!c||!c.owner)return;
    const who=typeof C.who==="function"?C.who():null;
    if(!who||who.id==null)return;
    const db=C.client&&C.client.database;
    if(!db||typeof db.from!=="function")return;
    const r=db.from("yb_gifts").insert({
      from_id:String(who.id),
      from_name:(typeof C.name==="function"?C.name():"家长"),
      to_id:String(c.owner),to_name:c.user||"",
      food:"rose",post_id:(p&&p.cloudId)||null
    });
    if(r&&typeof r.catch==="function")r.catch(()=>{});
  }catch(e){}
}
function openHelper(ci,scope){
  /* 两个列表各自对应自己的帖子：详情页用 curDetail，底部帮忙面板用 S.curPost。
     不能只看 curDetail —— 从详情页返回后它仍保留旧值，会张冠李戴。 */
  const pid=scope==="detail"?curDetail:S.curPost;
  const p=(S&&S.posts||[]).find(x=>x.id===pid);
  if(!p)return;
  const c=p.comments&&p.comments[ci];
  if(!c)return;
  const isMine=!!p.mine;
  const ava=c.user==="阳阳爸爸"?myAvaSVG():avatarSVG(c.ava);
  modal(`<div class="md-title">🌼 帮忙的家长</div>
    <div class="r23-hp">
      <div class="r23-hp-top">
        <div class="r23-hp-ava">${ava}</div>
        <div class="r23-hp-id">
          <b>${esc(c.user||"家长")} ${esc(c.flag||"")}</b>
          <span>${isMine?"帮了你的这条求助":"为这条求助伸出了援手"}${c.dur?" · "+esc(c.dur):""}</span>
        </div>
      </div>
      <div class="r23-hp-q">${helperQuote(c)}</div>
      <div class="r23-hp-acts">
        <button class="r23-hp-b food" id="r23HpFood">🍽️ 送份美食</button>
        <button class="r23-hp-b rose" id="r23HpRose">🌹 送朵玫瑰</button>
      </div>
      <div class="r23-hp-note">都是社区里的心意，不用花钱${c.rosed?" · 这条帮忙已收过你的玫瑰 🌹":""}</div>
    </div>
    <div class="md-acts"><button class="btn-g" data-x="close">关闭</button></div>`);
  const food=$("#r23HpFood"),rose=$("#r23HpRose");
  if(food)food.onclick=()=>{
    closeModal();
    if(window.YRB_FOOD&&YRB_FOOD.openPanel){
      YRB_FOOD.openPanel({name:c.user||"TA",id:c.owner||"",postId:p.cloudId||null});
    }else{
      toast("答谢面板还在加载，请稍后再试");
    }
  };
  if(rose)rose.onclick=()=>{
    closeModal();
    sendRose(p,ci);
  };
}
function sendRose(p,ci){
  p.roses=p.roses||[];
  const c=p.comments[ci];if(!c)return;
  /* 修复：玫瑰按「单条帮忙」去重（旧逻辑按用户名去重，同一用户第二条帮忙永远无法再收玫瑰） */
  if(c.rosed){toast("这条帮忙已收到你的玫瑰 🌹");return;}
  /* 玫瑰数由 openGift 内部 +1（app.js），此处不要再加，否则一次送花会 +2 */
  c.rosed=true;p.roses.push(c.user);
  openGift("满屏感谢",`你的玫瑰已送给 ${c.user} · ${p.roses.length} 朵玫瑰已抵达`);
  sendRoseToCloud(p,c);                 /* 云端记一笔，对方收件箱能看到 */
  if($("#r23Detail").classList.contains("open"))renderDetail();
  renderMe&&renderMe();
}
function renderDetail(){openDetail(curDetail);}

/* ============ 答谢入口：首页卡片一键答谢（2026-10-20 用户需求） ============
   「答谢入口要更明显」→ 每张有帮忙的卡片下方加一条 ❐ 答谢条，
   点开是帮忙名单，每位家长两个按钮：🌹 送玫瑰 / 🍽️ 送美食。 */
function renderThank(p){
  const cs=(p.comments||[]);
  const rows=cs.map((c,i)=>`<div class="tk-item">
    <span class="tk-ava">${avatarSVG(c.ava||"animal")}</span>
    <span class="tk-main"><b>${esc(c.user||"家长")}</b><i>${helperQuote(c)}</i></span>
    <span class="tk-acts">
      <button class="tk-b rose${c.rosed?" done":""}" data-tk-rose="${i}">🌹 ${c.rosed?"已送":"送玫瑰"}</button>
      <button class="tk-b food" data-tk-food="${i}">🍽️ 送美食</button>
    </span></div>`).join("");
  modal(`<div class="md-title">🍽️ 答谢帮忙的家长</div>
    <p class="tk-sub">每一份帮忙都值得被看见——送份美食或一朵玫瑰，让 TA 知道你收到了</p>
    <div class="tk-list">${rows}</div>
    <div class="md-acts"><button class="btn-g" data-x="close">稍后再送</button></div>`);
  $$("#mdCard [data-tk-rose]").forEach(b=>b.onclick=()=>{
    const i=+b.dataset.tkRose,c=cs[i];if(!c)return;
    if(c.rosed){toast("这条帮忙已经收到你的玫瑰啦 🌹");return;}
    closeModal();                       /* 满屏玫瑰动画在弹窗下层，先关弹窗才看得见 */
    sendRose(p,i);
  });
  $$("#mdCard [data-tk-food]").forEach(b=>b.onclick=()=>{
    const i=+b.dataset.tkFood,c=cs[i];if(!c)return;
    closeModal();
    if(window.YRB_FOOD&&YRB_FOOD.openPanel)YRB_FOOD.openPanel({name:c.user||"家长",id:c.owner||"",postId:p.cloudId||null});
    else toast("美食答谢正在加载，请稍后再试");
  });
}
async function openThank(id){
  const p=(S&&S.posts||[]).find(x=>x.id===id);if(!p)return;
  const C=window.YRB_CLOUD;
  if(!C||!C.signedIn||!C.signedIn()){
    toast("登录后才能答谢帮忙的家长～");
    if(C&&C.ensureLogin)setTimeout(()=>{try{C.ensureLogin();}catch(e){}},260);
    return;
  }
  /* 云端帖的帮忙留言是异步拉的：点答谢时按需加载一次 */
  if(p.__cloud&&C.ensureComments&&!(p.comments&&p.comments.length)){
    toast("正在读取帮忙名单…");
    try{await C.ensureComments(p);}catch(e){}
  }
  if(!(p.comments||[]).length){toast("这条求助还没有家长帮忙，暂时不能答谢");return;}
  renderThank(p);
}
document.addEventListener("click",e=>{
  const t=e.target.closest('[data-act="thank"]');if(!t)return;
  e.preventDefault();e.stopPropagation();
  const card=t.closest(".card");if(!card)return;
  openThank(+card.dataset.id);
},true);

/* ============ 举报 ============ */
let rpReason="";
function openReport(){
  $$("#r23RpGrid button").forEach(x=>x.classList.remove("on"));rpReason="";
  $("#r23Report").classList.add("open");
}
function submitReport(){
  rpReason=($$("#r23RpGrid button.on")||[{}])[0]?.dataset.r||"";   /* 2026-10-25 修复：原用 $（单元素）却按数组取 [0]，element[0] 恒 undefined，举报永远卡「请选择理由」 */
  if(!rpReason){toast("请选择举报理由");return;}
  $("#r23Report").classList.remove("open");
  toast("举报已提交，社区守护员将在 24 小时内处理 🛡");
}

/* ============ 启动 ============ */
injectAll();
window.YRB_R23=1;   /* 自愈标记：弱网补载用 */
})();
